insert into organizations (id, name, type, description, verification_status) values (
    'club-ai-society',
    'Trojan AI Society',
    'club',
    'Trojan AI Society is a student-run community for people who want to build and understand machine learning systems, from first-time Python users to graduate researchers. Members work in small project pods that ship a working model or demo every semester, and the club runs weekly paper-reading and hands-on workshop nights. We care more about curiosity and finishing projects than about prior experience.',
    'verified'
)
