insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-ai-society',
    'Trojan AI Society',
    'trojan-ai-society',
    'AI/ML',
    '["artificial_intelligence", "machine_learning", "deep_learning", "research", "hackathons", "python", "beginner_friendly"]'::jsonb,
    'Trojan AI Society is a student-run community for people who want to build and understand machine learning systems, from first-time Python users to graduate researchers. Members work in small project pods that ship a working model or demo every semester, and the club runs weekly paper-reading and hands-on workshop nights. We care more about curiosity and finishing projects than about prior experience.',
    'Trojan AI Society was founded in 2017 by four undergraduates who met in a crowded machine learning lecture and were frustrated that there was no place on campus to practice building models outside of class. They began as an informal Thursday reading group of about ten people sharing one whiteboard. In 2019 the group introduced semester-long project pods, which turned it from a discussion circle into a building community. In 2021 the club hosted its first student-run applied ML showcase, and in 2023 it launched a beginner track called Zero to Model so that students with no coding background could join. Today the society has roughly 180 active members across undergraduate and graduate programs, and its alumni mentor current pods each semester.',
    2017,
    '["Semester-long project pods of 4-6 students that build and demo an applied ML project", "Weekly paper-reading group covering one recent research paper in plain language", "Zero to Model beginner workshop series (Python, data handling, training a first model)", "Guest talks from alumni working as ML engineers and researchers", "An internal 24-hour model-building hackathon each fall", "Peer study sessions before internship interview season"]'::jsonb,
    '["Applied ML Showcase: end-of-semester demo night where every project pod presents", "Model Marathon: the club''s 24-hour internal hackathon held each October", "Research Roundtable: a spring panel where graduate students explain how to get into research", "Zero to Model kickoff in the second week of each semester"]'::jsonb,
    'General meetings Thursdays 6:30-8:00 PM; paper-reading group Mondays 5:00-6:00 PM; project pods schedule their own weekly work session.',
    'About 3-4 hours per week: one general meeting plus a project pod session. The reading group and workshops are optional.',
    3.5,
    'Open to all currently enrolled students, undergraduate or graduate, in any major. No prior machine learning or coding experience is required for the beginner track. Project pod members are expected to attend their pod''s weekly session.',
    'open',
    'Come to any Thursday general meeting and sign in; there is no application. Project pods form during the first three weeks of each semester, so join early if you want to be placed on a pod. Students who join later can attend workshops and the reading group right away and join a pod the following semester.',
    'Students who like learning by building, are comfortable asking basic questions, and will keep showing up for a team over a whole semester. Beginners who want structure and experienced students who want to mentor both do well here.',
    '[{"question": "Are beginners welcome?", "answer": "Yes. The Zero to Model track assumes no coding or machine learning background, and about a third of new members each semester start there."}, {"question": "Are there membership dues?", "answer": "Dues are $15 per semester and cover compute credits for project pods and food at the showcase. A dues waiver is available on request with no questions asked."}, {"question": "How much time does it take?", "answer": "Most members spend 3-4 hours a week: the Thursday general meeting plus one pod work session. Workshops and the reading group are optional."}, {"question": "Is there an application or interview?", "answer": "No. Membership is open. Pod placement uses a short interest form so you are matched to a project at your experience level, but nobody is rejected."}, {"question": "What do members actually do?", "answer": "Members join a project pod that builds one applied ML project over the semester, attend workshops, discuss research papers and present their work at the Applied ML Showcase."}, {"question": "Can graduate students join?", "answer": "Yes. Graduate students make up roughly a quarter of the membership and often lead pods or the paper-reading group."}, {"question": "Do I need my own GPU or paid tools?", "answer": "No. Pods use free notebook environments and shared compute credits paid for by club dues."}]'::jsonb,
    'hello@trojan-ai-society.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
