insert into organizations (id, name, type, description, verification_status) values (
    'club-founders-forge',
    'Founders Forge',
    'club',
    'Founders Forge is a student startup community where members turn ideas into tested products. Each semester a cohort of student teams goes through a ten-week build program with weekly customer-interview goals, mentor office hours and a final demo night. The club also runs open events for anyone curious about startups, whether or not they are in the cohort.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-founders-forge',
    'Founders Forge',
    'founders-forge',
    'Entrepreneurship',
    '["entrepreneurship", "startups", "product", "venture_capital", "pitching", "hackathons", "networking"]'::jsonb,
    'Founders Forge is a student startup community where members turn ideas into tested products. Each semester a cohort of student teams goes through a ten-week build program with weekly customer-interview goals, mentor office hours and a final demo night. The club also runs open events for anyone curious about startups, whether or not they are in the cohort.',
    'Founders Forge began in 2014 when two business students and an engineering student who had failed to launch a campus delivery app decided other students should not have to make the same mistakes alone. Their first program was a six-person accountability group that met in a library study room. In 2016 it became a structured ten-week cohort with volunteer alumni mentors. The first public Demo Night was held in 2018 and drew about 200 attendees. In 2022 the club added Idea Gym, an open weekly session for students who do not yet have a team or an idea. Around 60 student teams have completed the cohort program since it started.',
    2014,
    '["Ten-week build cohort for student startup teams with weekly milestones", "Idea Gym: open weekly session for brainstorming and finding co-founders", "Mentor office hours with alumni founders and early-stage operators", "Pitch practice nights with structured peer feedback", "Workshops on customer interviews, pricing, and building a first prototype", "A weekend build sprint co-hosted with other technical clubs"]'::jsonb,
    '["Demo Night: cohort teams present to students, alumni and invited guests at the end of each semester", "Co-Founder Mixer in the third week of each semester", "Forge Weekend: a 48-hour build sprint each spring", "Fail Forward Night: founders share what went wrong in past ventures"]'::jsonb,
    'Cohort sessions Tuesdays 7:00-9:00 PM; Idea Gym (open to everyone) Wednesdays 6:00-7:00 PM.',
    'Cohort members should expect 6-8 hours per week including team work. Open events such as Idea Gym take about 1 hour per week with no ongoing obligation.',
    7.0,
    'Open events are free for any enrolled student. The build cohort requires an application, a team of 1-4 people (solo applicants are matched where possible) and a commitment to attend at least eight of the ten sessions.',
    'application',
    'Anyone can attend Idea Gym or public events without signing up. To join the build cohort, submit the short written application during the first two weeks of the semester and attend a 15-minute conversation with two cohort leads. Decisions are shared within a week.',
    'Students who would rather test an idea with real users than polish a slide deck, who can take direct feedback, and who have time to commit to a team. You do not need a business background or an existing idea to benefit from the open sessions.',
    '[{"question": "Do I need a startup idea to join?", "answer": "Not for open events. Idea Gym exists for students without an idea or team. The cohort application does ask for a problem you want to work on, but it can be early."}, {"question": "Are beginners welcome?", "answer": "Yes. Many cohort members have never built a product before. Workshops cover the basics of customer interviews and prototyping."}, {"question": "Are there dues?", "answer": "No. Founders Forge does not charge dues. Events are funded by alumni donations and student programming funds."}, {"question": "What is the application process for the cohort?", "answer": "A short written form about the problem you want to solve and your availability, followed by a 15-minute conversation with two cohort leads. Applications open in the first two weeks of each semester."}, {"question": "How much time does the cohort take?", "answer": "Plan for 6-8 hours per week: a two-hour Tuesday session plus team work and customer interviews."}, {"question": "Does the club invest in or take equity from student startups?", "answer": "No. The club does not invest money and takes no equity or ownership in any team''s work."}, {"question": "Can graduate students apply?", "answer": "Yes. Cohorts usually include a mix of undergraduate and graduate students from many schools."}]'::jsonb,
    'team@founders-forge.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
on conflict (organization_id) do update set name = excluded.name, slug = excluded.slug, category = excluded.category, tags = excluded.tags, public_description = excluded.public_description, history = excluded.history, founded_year = excluded.founded_year, activities = excluded.activities, notable_events = excluded.notable_events, meeting_schedule = excluded.meeting_schedule, time_commitment = excluded.time_commitment, time_commitment_hours_per_week = excluded.time_commitment_hours_per_week, membership_requirements = excluded.membership_requirements, recruitment_status = excluded.recruitment_status, how_to_join = excluded.how_to_join, who_thrives_here = excluded.who_thrives_here, faq = excluded.faq, public_contact = excluded.public_contact, verification_status = excluded.verification_status, data_label = excluded.data_label, website = excluded.website, social_links = excluded.social_links, source_urls = excluded.source_urls, collected_at = excluded.collected_at;

insert into organizations (id, name, type, description, verification_status) values (
    'club-cardinal-capital',
    'Cardinal Capital Collective',
    'club',
    'Cardinal Capital Collective is a student organization that teaches investing and business problem-solving through practice. Analysts research companies for a paper-traded student portfolio and work in teams on pro bono consulting projects for small local businesses. New members go through an eight-week training program before joining a team.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-cardinal-capital',
    'Cardinal Capital Collective',
    'cardinal-capital-collective',
    'Finance & Consulting',
    '["finance", "investing", "consulting", "case_competitions", "career_development", "data_analysis"]'::jsonb,
    'Cardinal Capital Collective is a student organization that teaches investing and business problem-solving through practice. Analysts research companies for a paper-traded student portfolio and work in teams on pro bono consulting projects for small local businesses. New members go through an eight-week training program before joining a team.',
    'Cardinal Capital Collective was founded in 2011 by a group of economics students who wanted a finance club that was open to non-business majors. It started as a stock-pitch discussion group that tracked a mock portfolio on a shared spreadsheet. In 2015 the club added a consulting arm after a local bakery owner asked members for help with pricing. The eight-week analyst training program was introduced in 2018 to give every new member the same foundation in accounting, valuation and structured problem-solving. In 2020 the club moved its training online for a year and kept the recorded sessions as a permanent resource. It now has about 90 members split between the investment and consulting teams.',
    2011,
    '["Eight-week analyst training in accounting basics, valuation and case structuring", "Sector teams that research and pitch companies for a paper-traded portfolio", "Pro bono consulting projects for small businesses near campus", "Weekly market recap and discussion", "Resume reviews and mock interviews run by upperclass members", "Internal stock-pitch and case competitions"]'::jsonb,
    '["Fall Stock Pitch Night judged by alumni", "Spring Case Sprint: a one-day internal case competition", "Small Business Showcase where consulting teams present final recommendations to clients", "Finance Careers 101 open info night at the start of each semester"]'::jsonb,
    'General meeting Mondays 7:00-8:30 PM; analyst training Wednesdays 6:00-7:30 PM during the first eight weeks; teams meet once more on their own schedule.',
    'About 5-6 hours per week during analyst training and 4-5 hours per week afterward.',
    5.0,
    'Open to undergraduates and master''s students in any major. Admission is by application each fall and spring. No prior finance knowledge is assumed, but new members must complete the eight-week training program.',
    'application',
    'Attend an info night in the first two weeks of the semester, then submit the online application (resume plus two short answers). Shortlisted applicants are invited to a 20-minute conversational interview; there are no technical finance questions for new analysts.',
    'Students who enjoy digging into how businesses work, are willing to learn spreadsheets and present their reasoning, and want honest feedback. Non-business majors are common and do well.',
    '[{"question": "Do I need to be a business or economics major?", "answer": "No. Roughly half of current members are from engineering, sciences, and humanities. Training starts from the basics."}, {"question": "Are beginners welcome?", "answer": "Yes, the application does not test finance knowledge. Every new analyst takes the eight-week training program."}, {"question": "Are there dues?", "answer": "Dues are $25 per semester, which pay for data subscriptions and event costs. Fee assistance is available."}, {"question": "What is the application process?", "answer": "An online application with a resume and two short written answers, followed by a 20-minute conversational interview for shortlisted applicants. Applications are accepted at the start of fall and spring."}, {"question": "Does the club invest real money?", "answer": "No. The portfolio is paper-traded for learning purposes only. Nothing the club produces is financial advice."}, {"question": "How much time does it take?", "answer": "Around 5-6 hours per week during the eight weeks of training and 4-5 hours per week after that."}, {"question": "What do members actually do?", "answer": "After training, members join either a sector investment team that researches and pitches companies, or a consulting team that works with a local small business for a semester."}]'::jsonb,
    'recruiting@cardinal-capital.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
on conflict (organization_id) do update set name = excluded.name, slug = excluded.slug, category = excluded.category, tags = excluded.tags, public_description = excluded.public_description, history = excluded.history, founded_year = excluded.founded_year, activities = excluded.activities, notable_events = excluded.notable_events, meeting_schedule = excluded.meeting_schedule, time_commitment = excluded.time_commitment, time_commitment_hours_per_week = excluded.time_commitment_hours_per_week, membership_requirements = excluded.membership_requirements, recruitment_status = excluded.recruitment_status, how_to_join = excluded.how_to_join, who_thrives_here = excluded.who_thrives_here, faq = excluded.faq, public_contact = excluded.public_contact, verification_status = excluded.verification_status, data_label = excluded.data_label, website = excluded.website, social_links = excluded.social_links, source_urls = excluded.source_urls, collected_at = excluded.collected_at;

insert into organizations (id, name, type, description, verification_status) values (
    'club-robotics-guild',
    'Figueroa Robotics Guild',
    'club',
    'Figueroa Robotics Guild designs, builds and competes with autonomous robots. The club is organized into mechanical, electrical, software and operations subteams that work toward one competition robot each year, plus a smaller rookie build in the fall. Members get hands-on time with CAD, machining, circuit design and autonomy software.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-robotics-guild',
    'Figueroa Robotics Guild',
    'figueroa-robotics-guild',
    'Robotics',
    '["robotics", "engineering", "hardware", "embedded_systems", "computer_vision", "competitions", "cad"]'::jsonb,
    'Figueroa Robotics Guild designs, builds and competes with autonomous robots. The club is organized into mechanical, electrical, software and operations subteams that work toward one competition robot each year, plus a smaller rookie build in the fall. Members get hands-on time with CAD, machining, circuit design and autonomy software.',
    'The Figueroa Robotics Guild was started in 2009 by a handful of mechanical engineering students who built a line-following robot in a dorm common room and wanted to enter a regional competition. Their first entry did not finish its course, which became a club tradition: every year the team displays its biggest failure at the first meeting. The guild gained dedicated workshop space in 2013 and added a software subteam in 2016 when it moved to autonomous navigation. In 2019 it introduced the Rookie Rover program so that new members build a small robot from scratch before touching the competition robot. The guild reached the final round of a regional collegiate autonomy challenge in 2024.',
    2009,
    '["Designing and building the annual competition robot across four subteams", "Rookie Rover: an eight-week fall build program for new members", "Tool and safety certification sessions for the workshop", "Autonomy software nights focused on perception and path planning", "Outreach demos at local middle schools", "Design reviews with alumni engineers twice a semester"]'::jsonb,
    '["Rookie Rover Race Day at the end of the fall program", "Spring Robot Reveal and open workshop tour", "Regional collegiate autonomy challenge trip each April", "Failure Wall night at the first meeting of the year"]'::jsonb,
    'All-hands Sundays 2:00-3:00 PM; subteam build sessions Tuesdays and Thursdays 7:00-9:30 PM; extra open workshop hours on Saturdays before competition.',
    'About 6-8 hours per week in a normal week, rising to 10 or more in the three weeks before competition.',
    7.0,
    'Open to all enrolled students by application. Members must complete workshop safety certification before using tools and attend at least one build session per week. No prior robotics experience is needed for the Rookie Rover program.',
    'application',
    'Applications open during the first three weeks of the fall semester through a short form that asks which subteam interests you and your weekly availability. New members start in Rookie Rover. A smaller number of spots open in spring for subteams that need help.',
    'People who like making physical things work, do not mind debugging for hours, and can commit to regular evenings in the workshop. Students from any major are welcome, including operations-minded students who want to handle sponsorship, budgeting and logistics.',
    '[{"question": "Are beginners welcome?", "answer": "Yes. Rookie Rover is designed for students with no robotics experience and teaches basic CAD, wiring and programming."}, {"question": "Are there dues?", "answer": "Dues are $30 per year and help pay for parts and safety equipment. Competition travel is subsidized and members pay a reduced share."}, {"question": "What is the application like?", "answer": "A short form about your interests and availability. It is used mainly for subteam placement and to keep workshop numbers safe; the fall intake accepts most applicants who can meet the time commitment."}, {"question": "How much time does it take?", "answer": "Typically 6-8 hours per week, and more in the three weeks before the April competition."}, {"question": "Do I have to be an engineering major?", "answer": "No. The operations subteam handles budgeting, sponsorship outreach and travel, and the technical subteams have members from many majors."}, {"question": "What do members actually do?", "answer": "Members design parts in CAD, machine and assemble them, build and test circuits, write autonomy code and test the robot on a practice course. Rookies build their own small rover first."}]'::jsonb,
    'build@figueroa-robotics.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
