insert into organizations (id, name, type, description, verification_status) values (
    'club-pixel-foundry',
    'Pixel Foundry Game Studio',
    'club',
    'Pixel Foundry is a student game studio where programmers, artists, writers and composers make small games together. Every semester the club runs a jam-to-release cycle: a weekend jam to prototype ideas, then eight weeks of polishing the favorites into playable releases. No experience is needed, and there are roles for people who do not code.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-pixel-foundry',
    'Pixel Foundry Game Studio',
    'pixel-foundry-game-studio',
    'Game Development',
    '["game_development", "programming", "art", "sound_design", "storytelling", "game_jams", "beginner_friendly"]'::jsonb,
    'Pixel Foundry is a student game studio where programmers, artists, writers and composers make small games together. Every semester the club runs a jam-to-release cycle: a weekend jam to prototype ideas, then eight weeks of polishing the favorites into playable releases. No experience is needed, and there are roles for people who do not code.',
    'Pixel Foundry Game Studio was founded in 2015 by three friends, a programmer, an illustrator and a music student, who entered a weekend game jam together and realized they had no way to find collaborators from other majors. The first year consisted of monthly jams in a borrowed classroom. In 2017 the club adopted its jam-to-release cycle so that jam prototypes would actually get finished. Its first public Arcade Night in 2018 featured six student games on borrowed laptops. In 2021 the club started a mentorship pairing between new members and returning team leads, and in 2023 a member team''s puzzle game was selected for a regional student games showcase. The club has released more than 40 small games.',
    2015,
    '["Weekend game jams at the start of each semester", "Eight-week production teams that polish jam prototypes into finished games", "Skill workshops in game engines, pixel art, level design and game audio", "Weekly playtest night where teams swap builds and give feedback", "Portfolio review sessions with alumni working in the games industry"]'::jsonb,
    '["Kickoff Jam: a 48-hour game jam in the third week of the semester", "Arcade Night: a public showcase of finished student games each semester", "Tiny Games Challenge: a one-evening jam with a 3-hour limit", "Industry Portfolio Night each spring"]'::jsonb,
    'General meeting and playtest night Fridays 5:00-7:00 PM; production teams pick one additional weekly meeting time.',
    'About 3-5 hours per week on a production team. Attending only jams and workshops is fine and takes less.',
    4.0,
    'Open to all enrolled students. No portfolio, audition or coding experience required. Members who join a production team are asked to stay with it through Arcade Night.',
    'open',
    'Show up to any Friday meeting or to the Kickoff Jam; there is no application. Teams form at the jam, and members who join later are placed on an existing team by the production leads.',
    'People who love games and want to finish something, whatever their skill: coding, drawing, writing, music or simply organizing a team. Students who enjoy cross-disciplinary collaboration and giving kind, specific feedback fit well.',
    '[{"question": "Are beginners welcome?", "answer": "Yes. Workshops start from zero and every production team includes at least one returning member who mentors newcomers."}, {"question": "Do I need to know how to code?", "answer": "No. Teams need artists, writers, composers, sound designers, level designers and producers as much as programmers."}, {"question": "Are there dues?", "answer": "No dues. The club is funded through student programming funds, and all tools used in workshops are free."}, {"question": "How much time does it take?", "answer": "Production team members spend roughly 3-5 hours a week. You can also just attend jams and workshops with no weekly commitment."}, {"question": "Is there an application?", "answer": "No. Membership is open all semester."}, {"question": "What do members actually do?", "answer": "They prototype a game at the Kickoff Jam, then work on a small team for about eight weeks to finish it, playtest each other''s builds on Fridays and show the result at Arcade Night."}]'::jsonb,
    'play@pixel-foundry.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
