insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-design-collective',
    'Gold Line Design Collective',
    'gold-line-design-collective',
    'Design',
    '["design", "ux_design", "graphic_design", "product", "user_research", "portfolio", "creative"]'::jsonb,
    'Gold Line Design Collective is a community for students interested in UX, product and visual design. Members learn through weekly critique circles, skills workshops and semester-long studio projects for campus groups and nonprofits. The collective welcomes students from any major who want to build a design practice and a portfolio.',
    'Gold Line Design Collective was founded in 2018 by two students, one in communication and one in computer science, who kept meeting at the same campus cafe to critique each other''s app mockups. Their weekly critique grew to a dozen people within a semester, and they registered as a student organization that fall. In 2020 the collective began its Studio program, pairing student teams with campus groups and nonprofits that needed design help. A beginner Design Foundations series was added in 2021. In 2024 the collective held its first portfolio exhibition, displaying the work of 35 members. It currently has around 110 members.',
    2018,
    '["Weekly critique circles where members share work in progress", "Design Foundations workshop series on typography, layout, and interface design", "Studio projects: semester-long design work for campus groups and nonprofits", "User research practice sessions including interviews and usability tests", "Portfolio and case-study writing reviews", "A one-day designathon each fall"]'::jsonb,
    '["Fall Designathon: a one-day design sprint on a campus problem", "Spring Portfolio Exhibition", "Design Careers Panel with alumni designers", "Open Crit Night, a critique circle open to non-members"]'::jsonb,
    'Critique circles Wednesdays 7:00-8:30 PM; workshops on alternating Mondays 6:00-7:00 PM; Studio teams meet weekly at a time they choose.',
    'About 2-3 hours per week for general members; Studio project members should plan for 5 hours per week.',
    3.0,
    'Open to all enrolled students in any major. No portfolio is required to join. Studio projects have a short interest form because the number of client projects is limited.',
    'open',
    'Come to a Wednesday critique circle or any workshop and join the mailing list at sign-in. To be considered for a Studio project, fill out the interest form sent to members in the second week of the semester.',
    'Students who are curious about why things are designed the way they are, who are willing to show unfinished work, and who enjoy giving and receiving thoughtful critique. Engineers, writers and business students who want design skills are as welcome as art students.',
    '[{"question": "Are beginners welcome?", "answer": "Yes. The Design Foundations series is made for students who have never used a design tool, and critique circles include beginner-only groups."}, {"question": "Do I need a portfolio to join?", "answer": "No. Many members join in order to build their first portfolio piece."}, {"question": "Are there dues?", "answer": "Dues are $10 per semester to cover printing for the exhibition and workshop materials. They can be waived on request."}, {"question": "How much time does it take?", "answer": "General members spend 2-3 hours per week. Studio project members spend around 5 hours per week."}, {"question": "Is there an application?", "answer": "General membership has no application. Studio projects use a short interest form for team placement, and not everyone can be placed every semester."}, {"question": "What do members actually do?", "answer": "They bring work in progress to critique circles, attend skills workshops, and optionally join a Studio team that designs something real for a campus group or nonprofit."}]'::jsonb,
    'hello@goldline-design.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
