insert into organizations (id, name, type, description, verification_status) values (
    'club-rang-cultural-circle',
    'Rang South Asian Cultural Circle',
    'club',
    'Rang South Asian Cultural Circle celebrates and shares the cultures of South Asia through festivals, food, performance and conversation. The circle hosts large celebrations for Diwali and Holi, regular chai socials and a spring cultural showcase. Everyone is welcome regardless of background; many members join simply to learn and make friends.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-rang-cultural-circle',
    'Rang South Asian Cultural Circle',
    'rang-south-asian-cultural-circle',
    'Cultural',
    '["cultural", "south_asian", "community", "dance", "food", "festivals", "social"]'::jsonb,
    'Rang South Asian Cultural Circle celebrates and shares the cultures of South Asia through festivals, food, performance and conversation. The circle hosts large celebrations for Diwali and Holi, regular chai socials and a spring cultural showcase. Everyone is welcome regardless of background; many members join simply to learn and make friends.',
    'Rang, which means color in several South Asian languages, was founded in 2006 by a small group of international and second-generation students who wanted a place to celebrate festivals together when they could not travel home. The first event was a Diwali potluck for about thirty people in a residence hall lounge. By 2010 the Diwali celebration had outgrown the lounge and moved to a campus ballroom. The circle added its spring cultural showcase, Rang Manch, in 2012, featuring student dance, music and spoken word. In 2019 it began a mentorship program pairing new international students with returning members to help them settle in. The circle now has about 250 members and its festival events regularly draw several hundred attendees.',
    2006,
    '["Festival celebrations including Diwali, Holi and Eid gatherings", "Biweekly chai socials with games and conversation", "Open dance workshops in Bollywood, bhangra and classical styles", "Mentorship pairing for new and international students", "Community cooking nights", "Rehearsals for the spring cultural showcase (optional)"]'::jsonb,
    '["Diwali Night: the circle''s largest fall celebration with dinner and performances", "Holi on the Lawn each spring", "Rang Manch: the spring cultural showcase of student performances", "Welcome Chai for new students in the first week of fall"]'::jsonb,
    'Chai socials every other Friday 5:30-7:00 PM; dance workshops Saturdays 11:00 AM-12:30 PM; festival events on dates announced each semester.',
    'Flexible. Most members spend 1-2 hours per week; showcase performers and event volunteers spend more in the weeks before a big event.',
    2.0,
    'Open to all enrolled students of any background. There are no attendance requirements for general members.',
    'open',
    'Come to any chai social or festival event and sign up at the welcome table. You can join at any point in the year. Volunteer and performer sign-ups are announced on the mailing list before each major event.',
    'Students looking for a warm community, whether they want to stay connected to South Asian traditions or experience them for the first time. People who enjoy food, music, dancing or helping organize large events will find a place.',
    '[{"question": "Do I need to be South Asian to join?", "answer": "No. The circle is open to everyone, and many members join to learn about the cultures and meet people."}, {"question": "Are there dues?", "answer": "General membership is free. Some large events such as Diwali Night have a ticket price that covers dinner; members get a discount."}, {"question": "How much time does it take?", "answer": "As much or as little as you like. Typical involvement is 1-2 hours per week, with no attendance requirement."}, {"question": "Is there an application or audition?", "answer": "No application for membership. Performing in Rang Manch involves a friendly sign-up and placement session, not a competitive audition."}, {"question": "What do members actually do?", "answer": "They attend chai socials, celebrate festivals together, take dance workshops, cook, volunteer at events and, if they want, perform in the spring showcase."}, {"question": "Are beginners welcome at dance workshops?", "answer": "Yes. Workshops are taught at a beginner level and no dance experience is expected."}]'::jsonb,
    'namaste@rang-circle.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
