insert into organizations (id, name, type, description, verification_status) values (
    'club-midnight-marquee',
    'Midnight Marquee A Cappella',
    'club',
    'Midnight Marquee is an all-voices contemporary a cappella group of about sixteen singers. The group arranges its own music, performs two full concerts a year and sings at campus events throughout the semester. Membership is by audition at the start of the fall semester, and concerts are free and open to everyone.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-midnight-marquee',
    'Midnight Marquee A Cappella',
    'midnight-marquee-a-cappella',
    'Performing Arts',
    '["music", "singing", "a_cappella", "performing_arts", "performance", "arranging", "auditions"]'::jsonb,
    'Midnight Marquee is an all-voices contemporary a cappella group of about sixteen singers. The group arranges its own music, performs two full concerts a year and sings at campus events throughout the semester. Membership is by audition at the start of the fall semester, and concerts are free and open to everyone.',
    'Midnight Marquee A Cappella was founded in 2003 by six students who had sung together in a residence hall talent show and did not want to stop. The name comes from their first rehearsal slot, the only time a practice room was free: 11 PM to midnight. The group performed its first full concert in spring 2004 to an audience of about fifty. It began writing all of its own arrangements in 2008 and released its first student-produced recording in 2013. In 2017 the group started an annual free workshop for campus singers who are not members. The ensemble has stayed deliberately small, between fourteen and eighteen singers, so that every member has a featured part each year.',
    2003,
    '["Twice-weekly ensemble rehearsals", "Arranging sessions where members learn to write a cappella arrangements", "Two full concerts per year, in late fall and spring", "Short performances at campus events and student showcases", "An annual open vocal workshop for non-members"]'::jsonb,
    '["Fall Concert: Lights Down, held in early December", "Spring Concert: Encore, the group''s largest show of the year", "Open Voices Workshop: a free vocal workshop for any student", "Fall auditions during the second week of the fall semester"]'::jsonb,
    'Rehearsals Mondays and Thursdays 8:00-10:00 PM, with one extra Saturday rehearsal in the two weeks before each concert.',
    'About 5 hours per week for rehearsals and individual practice, with additional time during concert weeks.',
    5.0,
    'Membership is by audition, held once a year in the second week of the fall semester. Members commit to the full academic year and to attending both weekly rehearsals. Reading sheet music is helpful but not required.',
    'closed',
    'Auditions for this academic year have finished and the group is not adding members right now. The next auditions are in the second week of the fall semester: sign up for a 10-minute slot, prepare a verse and chorus of any song, and expect short pitch-matching exercises. Non-members are welcome at the Open Voices Workshop and at concerts.',
    'Singers who enjoy blending in a small group, can commit to two evening rehearsals every week, and like having a say in what the group sings. Beatboxers and students curious about arranging are especially encouraged to audition.',
    '[{"question": "Can I join right now?", "answer": "Not at the moment. The group auditions once a year in the second week of the fall semester and its roster is full until then. You can still come to the Open Voices Workshop and concerts."}, {"question": "Do I need formal vocal training?", "answer": "No. Several current members had never sung in a choir before auditioning. The audition looks at pitch, blend and willingness to learn."}, {"question": "What does the audition involve?", "answer": "A 10-minute slot in which you sing a verse and chorus of a song you choose, followed by short pitch-matching and range exercises. A small number of singers are invited to a group callback."}, {"question": "Are there dues?", "answer": "Dues are $40 per year, which help pay for recording and concert production. A payment plan or waiver is available."}, {"question": "How much time does it take?", "answer": "About 5 hours per week: two two-hour rehearsals plus individual practice, and extra rehearsals near concerts."}, {"question": "What do members actually do?", "answer": "Members rehearse twice a week, help choose and arrange the songs, perform at campus events and put on a full concert each semester."}]'::jsonb,
    'sing@midnight-marquee.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
