insert into organizations (id, name, type, description, verification_status) values (
    'club-expo-tutors',
    'Exposition Neighborhood Tutors',
    'club',
    'Exposition Neighborhood Tutors pairs university students with elementary and middle school students near campus for free weekly tutoring in reading and math. Volunteers commit to one after-school session per week and receive training before their first visit. The program focuses on steady relationships, so tutors work with the same students all semester.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-expo-tutors',
    'Exposition Neighborhood Tutors',
    'exposition-neighborhood-tutors',
    'Community Service',
    '["community_service", "volunteering", "tutoring", "education", "mentorship", "social_impact"]'::jsonb,
    'Exposition Neighborhood Tutors pairs university students with elementary and middle school students near campus for free weekly tutoring in reading and math. Volunteers commit to one after-school session per week and receive training before their first visit. The program focuses on steady relationships, so tutors work with the same students all semester.',
    'Exposition Neighborhood Tutors was founded in 2008 by a first-generation college student who had benefited from a volunteer tutor as a child and wanted to return the favor to the neighborhood around campus. The program began with nine volunteers at a single elementary school. In 2012 it expanded to a second school and added math support alongside reading. Volunteer training was formalized in 2016 with help from education graduate students, and a summer reading-kit drive began in 2018. During 2020 the program ran entirely over video calls and afterwards kept an online option for families who preferred it. About 120 volunteers now tutor at three partner sites each semester.',
    2008,
    '["Weekly after-school tutoring sessions in reading and math at partner sites", "Volunteer training on tutoring techniques and working with children", "Monthly reflection dinners for volunteers", "A book and school-supply drive each semester", "An end-of-year family celebration with partner schools"]'::jsonb,
    '["Volunteer Orientation and Training Day in the third week of each semester", "Read-a-thon: a spring reading celebration with tutees and families", "Summer Reading Kit Drive each April", "End-of-Year Family Celebration"]'::jsonb,
    'Tutoring sessions run Monday-Thursday 3:30-5:00 PM; each volunteer picks one day. Reflection dinners are the first Wednesday of the month at 6:30 PM.',
    'About 2.5 hours per week, including the session and walking or shuttle time to the partner site.',
    2.5,
    'Open to all enrolled students. Volunteers must attend one training session, complete the background screening required by partner schools, and commit to the same weekly session for the full semester.',
    'open',
    'Fill out the volunteer sign-up form during the first four weeks of the semester and choose a weekly day. You will be invited to the next training session and to complete the school-required background screening before your first visit.',
    'Patient, reliable students who enjoy working with kids and can keep a weekly commitment. No teaching experience is needed; consistency matters most.',
    '[{"question": "Do I need tutoring or teaching experience?", "answer": "No. All volunteers attend a training session before their first visit and get lesson materials each week."}, {"question": "Are there dues?", "answer": "No. Volunteering is free, and the club covers shuttle costs to partner sites."}, {"question": "How much time does it take?", "answer": "About 2.5 hours per week for one after-school session, plus an optional monthly reflection dinner."}, {"question": "Is there an application?", "answer": "There is a sign-up form rather than a competitive application. Volunteers do need to complete a training session and the background screening that partner schools require."}, {"question": "Can I join mid-semester?", "answer": "Sign-ups close after the fourth week so that tutees have a consistent tutor. Students who miss the window can help with the supply drive and join tutoring the next semester."}, {"question": "What do volunteers actually do?", "answer": "Each week they work with the same one or two children on reading or math using materials provided by the program, then log a short note about progress."}]'::jsonb,
    'volunteer@expo-tutors.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
