insert into organizations (id, name, type, description, verification_status) values (
    'club-canopy-sustainability',
    'Canopy Sustainability Collective',
    'club',
    'Canopy Sustainability Collective works on practical environmental projects on and around campus. Members tend a campus garden plot, run move-out donation and repair programs, and organize student campaigns on waste and energy. Project teams let members choose between hands-on work and policy or advocacy work.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-canopy-sustainability',
    'Canopy Sustainability Collective',
    'canopy-sustainability-collective',
    'Sustainability',
    '["sustainability", "environment", "climate", "gardening", "advocacy", "community_service", "zero_waste"]'::jsonb,
    'Canopy Sustainability Collective works on practical environmental projects on and around campus. Members tend a campus garden plot, run move-out donation and repair programs, and organize student campaigns on waste and energy. Project teams let members choose between hands-on work and policy or advocacy work.',
    'Canopy Sustainability Collective was formed in 2012 when a campus gardening group and a recycling advocacy group merged, having realized they shared most of their members. Its first joint project was a compost pilot in two residence halls. In 2015 the collective launched Second Life, a move-out donation drive that keeps furniture and clothing out of landfill, which now collects several tons of items each May. A monthly Repair Cafe began in 2019, where volunteers help students fix clothes, bikes and small electronics. In 2022 the collective published its first student-written campus waste audit. It has about 140 members across four project teams.',
    2012,
    '["Weekly work sessions at the campus garden plot", "Second Life move-out donation drive each May", "Monthly Repair Cafe for clothes, bikes and small electronics", "Student waste audits and campaign planning", "Native-plant and tree-care volunteer days", "Documentary screenings and speaker evenings"]'::jsonb,
    '["Earth Week Fair each April with student project booths", "Second Life Move-Out Drive in May", "Fall Harvest Dinner cooked from the garden plot", "Monthly Repair Cafe"]'::jsonb,
    'General meeting Tuesdays 6:00-7:00 PM; garden work sessions Saturdays 9:30-11:30 AM; Repair Cafe on the second Sunday of each month.',
    'About 2-3 hours per week: the general meeting plus one project activity. Everything beyond the general meeting is optional.',
    2.5,
    'Open to all enrolled students in any major. There are no requirements beyond joining at least one project team if you want voting membership.',
    'open',
    'Attend a Tuesday general meeting or drop in on a Saturday garden session. Sign-in adds you to the mailing list, and you can pick a project team at any time during the semester.',
    'Students who want to do something tangible about environmental issues, whether that means digging in a garden, fixing a bike or writing a policy proposal. People who prefer practical action and small teams tend to enjoy it.',
    '[{"question": "Are beginners welcome?", "answer": "Yes. No gardening, repair or environmental science background is needed, and each project team teaches what you need."}, {"question": "Are there dues?", "answer": "No dues. Tools, seeds and materials are provided by the collective."}, {"question": "How much time does it take?", "answer": "Most members spend 2-3 hours per week. You can attend only the activities that interest you."}, {"question": "Is there an application?", "answer": "No. Membership is open and you can join at any point in the semester."}, {"question": "What do members actually do?", "answer": "They join a project team: garden, Repair Cafe, Second Life donation drive, or campaigns. Teams plan and run their own activities and report back at the Tuesday meeting."}, {"question": "Do I need to study environmental science?", "answer": "No. Members come from engineering, business, arts and many other fields."}]'::jsonb,
    'grow@canopy-collective.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
