insert into organizations (id, name, type, description, verification_status) values (
    'club-peaks-and-trails',
    'Peaks & Trails Outdoor Club',
    'club',
    'Peaks & Trails gets students outside. The club runs weekend day hikes, beginner-friendly camping trips and indoor climbing nights, all led by trained student trip leaders. Trips are graded by difficulty so newcomers can find something comfortable, and gear can be borrowed from the club''s gear closet.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-peaks-and-trails',
    'Peaks & Trails Outdoor Club',
    'peaks-and-trails-outdoor-club',
    'Outdoors & Sports',
    '["outdoors", "hiking", "camping", "climbing", "fitness", "sports", "social"]'::jsonb,
    'Peaks & Trails gets students outside. The club runs weekend day hikes, beginner-friendly camping trips and indoor climbing nights, all led by trained student trip leaders. Trips are graded by difficulty so newcomers can find something comfortable, and gear can be borrowed from the club''s gear closet.',
    'Peaks & Trails Outdoor Club was founded in 2010 by three students from out of state who wanted to explore Southern California''s mountains and deserts but did not have cars or camping gear. They began by organizing carpools to local trailheads. In 2013 the club built its gear closet from donated tents, packs and stoves so that cost would not keep anyone from joining a trip. A formal trip-leader training program, including wilderness first aid certification, started in 2016. The club added weekly indoor climbing nights in 2018 and an annual desert stargazing campout in 2021. It runs roughly 30 trips a year for about 300 participating students.',
    2010,
    '["Weekend day hikes graded easy, moderate and strenuous", "Overnight camping and backpacking trips", "Weekly indoor climbing night at a nearby gym", "Trip-leader training with wilderness first aid certification", "Gear closet lending for tents, packs, sleeping bags and stoves", "Trail cleanup volunteer days"]'::jsonb,
    '["First Steps Hike: a beginner sunrise hike in the second week of each semester", "Desert Stargazing Campout each November", "Spring Break Backpacking Trip", "Trail Stewardship Day with a local trail volunteer group"]'::jsonb,
    'Trip planning meeting Wednesdays 7:00-7:45 PM; climbing night Thursdays 7:00-9:00 PM; hikes most Saturdays and one overnight trip per month.',
    'Entirely flexible. Sign up for the trips you want; a typical active member joins two or three outings a month, averaging around 3 hours per week.',
    3.0,
    'Open to all enrolled students. Participants sign a trip waiver and attend a short safety briefing before their first trip. Some strenuous trips require having completed an easier club trip first.',
    'open',
    'Come to a Wednesday planning meeting or sign up for a trip through the weekly trip email. Pay semester dues at your first trip. You can join at any time of year.',
    'Anyone who wants to spend time outdoors and meet people away from campus, from first-time hikers to experienced backpackers. Students who are happy to carpool, share snacks and look out for the slowest hiker fit the culture.',
    '[{"question": "Are beginners welcome?", "answer": "Yes. Every month includes easy-graded hikes and at least one beginner camping trip, and trip leaders set the pace for the group."}, {"question": "Do I need my own gear or a car?", "answer": "No. The gear closet lends tents, packs, sleeping bags and stoves for free, and trips use carpools arranged by trip leaders."}, {"question": "Are there dues?", "answer": "Dues are $20 per semester. Overnight trips have an additional cost share for gas, food and campsite fees, usually $15-$40. Financial assistance is available."}, {"question": "How much time does it take?", "answer": "It is up to you. There is no attendance requirement; most active members join two or three outings a month."}, {"question": "Is there an application?", "answer": "No. Membership is open. Popular trips fill up, so spots go to those who sign up first, with priority for people who have not been on a trip yet."}, {"question": "What do members actually do?", "answer": "They go on hikes, camping and backpacking trips, climb indoors on Thursdays, and can train to become trip leaders."}, {"question": "How do trip leaders handle safety?", "answer": "Trip leaders complete the club''s training and hold wilderness first aid certification. Every trip has a published difficulty grade and a safety briefing."}]'::jsonb,
    'trips@peaks-and-trails.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
