insert into organizations (id, name, type, description, verification_status) values (
    'club-pulse-prehealth',
    'Pulse Pre-Health Pathways',
    'club',
    'Pulse Pre-Health Pathways supports students exploring careers in medicine, nursing, dentistry, pharmacy, public health and other health fields. The club offers peer mentorship, panels with health professionals and students in professional programs, and group volunteering. It is meant to make the pre-health path less confusing and less lonely.',
    'verified'
)
on conflict (id) do update set name = excluded.name, type = excluded.type, description = excluded.description, verification_status = excluded.verification_status;

insert into club_profiles (organization_id, name, slug, category, tags, public_description, history, founded_year, activities, notable_events, meeting_schedule, time_commitment, time_commitment_hours_per_week, membership_requirements, recruitment_status, how_to_join, who_thrives_here, faq, public_contact, verification_status, data_label, website, social_links, source_urls, collected_at) values (
    'club-pulse-prehealth',
    'Pulse Pre-Health Pathways',
    'pulse-pre-health-pathways',
    'Pre-Health',
    '["pre_health", "pre_med", "healthcare", "mentorship", "volunteering", "career_development", "public_health"]'::jsonb,
    'Pulse Pre-Health Pathways supports students exploring careers in medicine, nursing, dentistry, pharmacy, public health and other health fields. The club offers peer mentorship, panels with health professionals and students in professional programs, and group volunteering. It is meant to make the pre-health path less confusing and less lonely.',
    'Pulse Pre-Health Pathways was founded in 2013 by three sophomores who felt lost navigating pre-medical requirements and found that most advice passed informally between friends. They started with a shared document of course tips and a monthly question-and-answer evening with seniors. In 2015 the club launched its peer mentorship families, small groups mixing first-years with upperclass students. It broadened its name and mission in 2018 from pre-med only to all health careers after members interested in nursing and public health asked to be included. A community health volunteering program with a neighborhood health fair began in 2021. The club has around 200 members.',
    2013,
    '["Peer mentorship families that mix new and experienced pre-health students", "Panels with health professionals and students in professional programs", "Workshops on course planning, personal statements and interview practice", "Group volunteering at community health fairs", "Study groups for common prerequisite courses", "Wellness and burnout-prevention evenings"]'::jsonb,
    '["Health Careers Night: a fall panel covering six different health professions", "Mentorship Family Reveal in the fourth week of fall", "Community Health Fair volunteering day each spring", "Application Bootcamp for students applying to professional programs"]'::jsonb,
    'General meetings every other Tuesday 7:00-8:00 PM; mentorship families meet monthly at times they arrange; study groups run weekly during midterm and finals periods.',
    'About 1-2 hours per week on average. Volunteering days and study groups are optional additions.',
    1.5,
    'Open to all enrolled students considering any health career. No GPA or major requirement. Mentors must have completed at least two semesters as a member.',
    'open',
    'Attend any general meeting and fill out the member form. To be placed in a mentorship family, complete the matching survey by the third week of fall; students who join later are added to an existing family in spring.',
    'Students who are curious about health careers and want honest guidance from peers a few steps ahead. It suits people who value a supportive, non-competitive atmosphere, including those still deciding whether a health career is right for them.',
    '[{"question": "Is this only for pre-med students?", "answer": "No. The club covers medicine, nursing, dentistry, pharmacy, physical therapy, physician assistant programs and public health."}, {"question": "Are first-year students and beginners welcome?", "answer": "Yes. The mentorship families are designed specifically for students who are new to the pre-health path."}, {"question": "Are there dues?", "answer": "Dues are $10 per year and cover event food and volunteering transport. They can be waived on request."}, {"question": "How much time does it take?", "answer": "About 1-2 hours per week on average, with optional volunteering and study groups."}, {"question": "Is there an application?", "answer": "No. Membership is open. The only form is a matching survey for mentorship families."}, {"question": "Does the club offer clinical shadowing placements?", "answer": "No. The club does not arrange shadowing or clinical placements. Panels and workshops explain how students typically find those opportunities on their own."}, {"question": "What do members actually do?", "answer": "They meet with their mentorship family, attend panels and workshops, join study groups for prerequisite courses and volunteer together at community health fairs."}]'::jsonb,
    'hello@pulse-prehealth.example.edu',
    'verified',
    'demo',
    '',
    '{}'::jsonb,
    '[]'::jsonb,
    null
)
